{
  "assumptions": [
    "Linearized around mid-wave operating point (arm ~45 deg lift) with small angles.",
    "SG90 servo modeled as linear DC motor + gearbox + light plastic arm; internal servo potentiometer loop approximated as open motor with integrator.",
    "Gear backlash, static friction, deadband and PWM saturation nonlinearity ignored except for uMin/uMax limits.",
    "Battery pack assumed ideal 4.8-5.0 V source; ESP32 PWM and control computation delay neglected.",
    "PIR trigger and OLED face are supervisory logic and not included in motion dynamics; wave reference is a step to 1 rad for tuning.",
    "Arm load is a light hollow plastic link; aerodynamic drag neglected."
  ],
  "controller": {
    "N": 80.0,
    "Q": [],
    "R": 1.0,
    "kd": 0.07,
    "ki": 6.0,
    "kp": 4.5,
    "type": "pid"
  },
  "controllerRationale": "Motor + inertia gives Type-1 plant 22.5/(s(s+12.5)). PD places dominant poles to wn~10 rad/s zeta~0.7 for ~0.6s settling and <15% overshoot, I removes friction steady error. N=80 (~8x bandwidth) filters derivative without adding phase. Gains are starting IMC/pole-placement guess for iteration.",
  "domain": "electromechanical",
  "equations": [
    "J dω/dt + b ω = Kt i - tau_load",
    "L di/dt + R i = V - Ke ω",
    "dθ/dt = ω",
    "Simplified to J_eq dω/dt + b_eq ω = Kq V with tau_load=0"
  ],
  "input": {
    "name": "servo motor voltage",
    "unit": "V"
  },
  "output": {
    "name": "arm wave angle",
    "unit": "rad"
  },
  "params": [
    {
      "name": "equivalent inertia at output",
      "symbol": "J_eq",
      "unit": "kg*m^2",
      "value": 0.00012
    },
    {
      "name": "equivalent viscous damping",
      "symbol": "b_eq",
      "unit": "N*m*s/rad",
      "value": 0.00027
    },
    {
      "name": "steady speed gain",
      "symbol": "K",
      "unit": "rad/s/V",
      "value": 1.8
    },
    {
      "name": "mechanical time constant",
      "symbol": "tau",
      "unit": "s",
      "value": 0.08
    },
    {
      "name": "SG90 stall torque at 4.8V",
      "symbol": "tau_stall",
      "unit": "N*m",
      "value": 0.18
    },
    {
      "name": "SG90 no-load speed",
      "symbol": "omega_nl",
      "unit": "rad/s",
      "value": 8.7
    },
    {
      "name": "waving link length",
      "symbol": "l_arm",
      "unit": "m",
      "value": 0.08
    },
    {
      "name": "waving link mass",
      "symbol": "m_arm",
      "unit": "kg",
      "value": 0.015
    }
  ],
  "plant": {
    "A": [],
    "B": [],
    "C": [],
    "delay": 0.0,
    "den": [
      0.08,
      1.0,
      0.0
    ],
    "kind": "tf",
    "num": [
      1.8
    ],
    "stateNames": []
  },
  "rig": {
    "kind": "arm",
    "signal": "angle"
  },
  "sim": {
    "disturbanceMagnitude": 0.0,
    "disturbanceTime": -1.0,
    "ref": 1.0,
    "tEnd": 3.0
  },
  "specs": {
    "maxOvershootPct": 15.0,
    "maxSettlingTime": 0.8,
    "maxSsErrorPct": 2.0,
    "uMax": 5.0,
    "uMin": -5.0
  },
  "summary": "Small PIR-triggered desktop buddy with a 2x SG90 pan-tilt waving arm powered by ESP32 and AA pack. We model the wave-axis DC-motor plus arm inertia from motor voltage to arm angle and control it to quickly wave hello when a person approaches.",
  "title": "Desktop Waving Buddy Arm"
}
